[
 {
  "name": "Premium rates rise",
  "why": "Plan A buys its extra treatments at initiative rates and has only EUR 0.1 million to spare, so dearer bought-in activity pushes it over the budget.",
  "changes": {
   "cost_initiative": 2400
  }
 },
 {
  "name": "Late start",
  "why": "If contracts and staff take nine months to arrange, long waits pile up before the initiative begins, adding long-wait months Plan A cannot win back.",
  "changes": {
   "policy_start": 9
  }
 },
 {
  "name": "Demand outgrows capacity",
  "why": "With referrals growing at 5% a year and capacity at 1%, the gap reopens fast once the initiative ends, and long waits climb again before 2028.",
  "changes": {
   "referral_growth": 0.05,
   "capacity_growth": 0.01
  }
 },
 {
  "name": "Weak validation, busier start",
  "why": "If validation removes only 5% of the list and referrals start higher than assumed, the one-off cut is smaller and is regained sooner.",
  "changes": {
   "validation_yield": 0.05,
   "referrals_base": 5600
  }
 },
 {
  "name": "Ageing population surge",
  "why": "A faster-ageing catchment could push referral growth to 7% a year, overwhelming a temporary measure.",
  "changes": {
   "referral_growth": 0.07
  }
 },
 {
  "name": "Burnout after the blitz",
  "why": "An initiative run on overtime wears staff out; if more leave afterwards, capacity falls below its trend just as the extra capacity ends.",
  "changes": {
   "staff_attrition": 0.1
  }
 }
]
